import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ResearchConfig {
  industry: string;
  focusAreas: string[];
  targetAudience: string;
  geography: string;
  timeHorizon: string;
  reportDepth: string;
  outputLanguage: 'English' | 'Chinese';
  outputFormat: 'Markdown' | 'Word' | 'PPT';
  additionalNotes: string;
}

export type SourceType = 'document' | 'url';

export interface Source {
  id: string;
  type: SourceType;
  name: string; // Filename or Page Title
  content: string; // Extracted text content
  metadata?: {
    size?: string;
    url?: string;
    uploadTime: string;
    status: 'pending' | 'processing' | 'indexed' | 'failed';
  };
}

export interface ReportCitation {
  sourceName: string;
  quote: string;
  pageOrSection?: string;
}

export interface GeneratedReport {
  executiveSummary: string;
  fullReport: string; // Markdown
  keyTakeaways: string[];
  citations: ReportCitation[];
  generationTime: string;
  model: string;
}

export type ViewState = 'input' | 'generating' | 'report' | 'history';

import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedReport, ResearchConfig, Source } from "../types";

// In a real app, this would be chunked and retrieved via vector search.
// Here we simulate RAG by passing the source content in the prompt context window.
const constructPrompt = (config: ResearchConfig, sources: Source[]): string => {
  const sourceContext = sources
    .map((s, i) => `[Source ${i + 1}: ${s.name}] type: ${s.type}\nContent snippet: ${s.content.slice(0, 2000)}...`) // Truncate for demo limits
    .join("\n\n");

  return `
You are a senior industry analyst at a top-tier strategy consulting firm.
Your task is to generate a professional industry report based strictly on the user's requirements and the provided knowledge base sources.

RESEARCH PARAMETERS:
- Industry/Topic: ${config.industry}
- Focus Areas: ${config.focusAreas.join(", ")}
- Target Audience: ${config.targetAudience}
- Geography: ${config.geography}
- Time Horizon: ${config.timeHorizon}
- Depth: ${config.reportDepth}
- Language: ${config.outputLanguage}

KNOWLEDGE BASE (CONTEXT):
${sourceContext || "No specific documents provided. Rely on general professional knowledge."}

INSTRUCTIONS:
1. Synthesize the provided sources to answer the research parameters.
2. If sources are insufficient, use your internal knowledge but mark assumptions clearly.
3. Structure the output into 4 distinct parts: Executive Summary, Full Report (Markdown), Key Takeaways (list), and Citations.
4. The Full Report MUST cover: Industry Definition, Market Overview, Key Trends, Competitive Landscape, Policy, Opportunities/Risks, Future Outlook, Recommendations.
5. Be professional, neutral, and data-driven.

Output JSON strictly adhering to the schema.
`;
};

export const generateIndustryReport = async (
  config: ResearchConfig,
  sources: Source[]
): Promise<GeneratedReport> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("API Key not found");

    const ai = new GoogleGenAI({ apiKey });
    const prompt = constructPrompt(config, sources);

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // Use a fast, high-quality model
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            executiveSummary: { type: Type.STRING },
            fullReport: { type: Type.STRING, description: "The detailed report in Markdown format" },
            keyTakeaways: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            citations: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  sourceName: { type: Type.STRING },
                  quote: { type: Type.STRING },
                  pageOrSection: { type: Type.STRING }
                }
              }
            }
          },
          required: ["executiveSummary", "fullReport", "keyTakeaways", "citations"]
        }
      }
    });

    if (!response.text) {
      throw new Error("No response generated");
    }

    const data = JSON.parse(response.text);

    return {
      ...data,
      generationTime: new Date().toISOString(),
      model: "gemini-3-flash-preview"
    };

  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  isLoading, 
  className = '', 
  disabled,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 focus:ring-indigo-500",
    secondary: "bg-slate-800 text-white hover:bg-slate-900 focus:ring-slate-500",
    outline: "border border-slate-300 bg-transparent text-slate-700 hover:bg-slate-50 focus:ring-indigo-500 dark:border-slate-600 dark:text-slate-200 dark:hover:bg-slate-800",
    ghost: "bg-transparent text-slate-600 hover:bg-slate-100 hover:text-slate-900 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-slate-100",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-500",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-4 py-2 text-sm",
    lg: "px-6 py-3 text-base",
  };

  return (
    <button
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <svg className="animate-spin -ml-1 mr-2 h-4 w-4" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      ) : null}
      {children}
    </button>
  );
};

