import React, { useState, useRef } from 'react';
import { Upload, Link as LinkIcon, FileText, Trash2, Globe, CheckCircle, Clock } from 'lucide-react';
import { Source } from '../types';
import { Button } from './ui/Button';
import { Input } from './ui/Input';
import { Card } from './ui/Card';
import { Badge } from './ui/Badge';

interface SourceManagerProps {
  sources: Source[];
  onAddSource: (source: Source) => void;
  onRemoveSource: (id: string) => void;
}

export const SourceManager: React.FC<SourceManagerProps> = ({ sources, onAddSource, onRemoveSource }) => {
  const [activeTab, setActiveTab] = useState<'docs' | 'urls'>('docs');
  const [urlInput, setUrlInput] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    Array.from(files).forEach((file) => {
      // Simulate reading/parsing file
      const reader = new FileReader();
      reader.onload = (event) => {
        const text = event.target?.result as string;
        const newSource: Source = {
          id: Math.random().toString(36).substr(2, 9),
          type: 'document',
          name: file.name,
          content: text || `[Binary content of ${file.name} simulated]`, // In real app, proper parsing
          metadata: {
            size: (file.size / 1024).toFixed(1) + ' KB',
            uploadTime: new Date().toLocaleTimeString(),
            status: 'indexed'
          }
        };
        onAddSource(newSource);
      };
      // Read as text for simplicity in this demo
      reader.readAsText(file);
    });

    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleUrlAdd = () => {
    if (!urlInput.trim()) return;

    // Simulate crawling
    const newSource: Source = {
      id: Math.random().toString(36).substr(2, 9),
      type: 'url',
      name: urlInput.replace(/^https?:\/\//, '').split('/')[0] + ' (Web Page)',
      content: `[Simulated crawled content from ${urlInput}]`,
      metadata: {
        url: urlInput,
        uploadTime: new Date().toLocaleTimeString(),
        status: 'indexed'
      }
    };
    onAddSource(newSource);
    setUrlInput('');
  };

  return (
    <div className="space-y-6">
      <div className="flex space-x-4 border-b border-slate-200 dark:border-slate-800 pb-2">
        <button
          className={`pb-2 text-sm font-medium ${activeTab === 'docs' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
          onClick={() => setActiveTab('docs')}
        >
          <div className="flex items-center"><FileText className="w-4 h-4 mr-2" />Documents</div>
        </button>
        <button
          className={`pb-2 text-sm font-medium ${activeTab === 'urls' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
          onClick={() => setActiveTab('urls')}
        >
          <div className="flex items-center"><LinkIcon className="w-4 h-4 mr-2" />Web Sources</div>
        </button>
      </div>

      {activeTab === 'docs' && (
        <div className="space-y-4">
           <div className="border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-lg p-8 text-center hover:bg-slate-50 dark:hover:bg-slate-900/50 transition-colors cursor-pointer" onClick={() => fileInputRef.current?.click()}>
              <Upload className="mx-auto h-12 w-12 text-slate-400" />
              <div className="mt-4 text-sm text-slate-600 dark:text-slate-400">
                <span className="font-semibold text-indigo-600 hover:text-indigo-500">Click to upload</span> or drag and drop
              </div>
              <p className="text-xs text-slate-500 mt-2">PDF, DOCX, TXT up to 10MB</p>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                multiple 
                accept=".txt,.md,.csv,.json" // Limited types for demo simplicity, real app handles PDF parsing
                onChange={handleFileUpload}
              />
           </div>
        </div>
      )}

      {activeTab === 'urls' && (
        <div className="flex space-x-2">
          <Input 
            placeholder="https://example.com/market-report" 
            value={urlInput} 
            onChange={(e) => setUrlInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleUrlAdd()}
          />
          <Button onClick={handleUrlAdd} disabled={!urlInput}>Add URL</Button>
        </div>
      )}

      {/* Source List */}
      <div className="space-y-3 max-h-96 overflow-y-auto">
        {sources.length === 0 && (
          <div className="text-center py-8 text-slate-500 text-sm">No sources added yet. The AI will rely on general knowledge.</div>
        )}
        {sources.map((source) => (
          <div key={source.id} className="flex items-center justify-between p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg shadow-sm">
            <div className="flex items-center space-x-3 overflow-hidden">
              <div className={`p-2 rounded-lg ${source.type === 'document' ? 'bg-blue-50 text-blue-600' : 'bg-purple-50 text-purple-600'}`}>
                {source.type === 'document' ? <FileText size={18} /> : <Globe size={18} />}
              </div>
              <div className="min-w-0">
                <p className="text-sm font-medium text-slate-900 dark:text-slate-100 truncate">{source.name}</p>
                <div className="flex items-center text-xs text-slate-500 space-x-2">
                  <span>{source.metadata?.size || 'Web Source'}</span>
                  <span>•</span>
                  <span className="flex items-center text-emerald-600"><CheckCircle size={10} className="mr-1" /> Indexed</span>
                </div>
              </div>
            </div>
            <button onClick={() => onRemoveSource(source.id)} className="text-slate-400 hover:text-red-500 transition-colors p-2">
              <Trash2 size={16} />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { ResearchConfig } from '../types';
import { FOCUS_AREAS, GEOGRAPHIES, REPORT_DEPTHS, TARGET_AUDIENCES, TIME_HORIZONS } from '../constants';
import { Input } from './ui/Input';
import { Select } from './ui/Select';
import { Card } from './ui/Card';
import { Badge } from './ui/Badge';

interface ResearchFormProps {
  config: ResearchConfig;
  onChange: (newConfig: ResearchConfig) => void;
}

export const ResearchForm: React.FC<ResearchFormProps> = ({ config, onChange }) => {

  const toggleFocusArea = (areaId: string) => {
    const newAreas = config.focusAreas.includes(areaId)
      ? config.focusAreas.filter(id => id !== areaId)
      : [...config.focusAreas, areaId];
    onChange({ ...config, focusAreas: newAreas });
  };

  return (
    <div className="space-y-6">
      <Card title="Core Research Parameters">
        <div className="space-y-4">
          <Input
            label="Industry or Research Topic"
            placeholder="e.g. Enterprise SaaS in Southeast Asia"
            value={config.industry}
            onChange={(e) => onChange({ ...config, industry: e.target.value })}
            className="font-medium"
          />

          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Focus Areas</label>
            <div className="flex flex-wrap gap-2">
              {FOCUS_AREAS.map((area) => {
                const isSelected = config.focusAreas.includes(area.id);
                const Icon = area.icon;
                return (
                  <div
                    key={area.id}
                    onClick={() => toggleFocusArea(area.id)}
                    className={`
                      cursor-pointer flex items-center px-3 py-2 rounded-lg text-sm font-medium border transition-all duration-200
                      ${isSelected 
                        ? 'bg-indigo-50 border-indigo-200 text-indigo-700 dark:bg-indigo-900/30 dark:border-indigo-800 dark:text-indigo-300' 
                        : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50 dark:bg-slate-900 dark:border-slate-700 dark:text-slate-400 dark:hover:bg-slate-800'}
                    `}
                  >
                    <Icon size={14} className={`mr-2 ${isSelected ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-400'}`} />
                    {area.label}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </Card>

      <Card title="Context & Output">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Select
            label="Target Audience"
            options={TARGET_AUDIENCES}
            value={config.targetAudience}
            onChange={(e) => onChange({ ...config, targetAudience: e.target.value })}
          />
          <Select
            label="Geography"
            options={GEOGRAPHIES}
            value={config.geography}
            onChange={(e) => onChange({ ...config, geography: e.target.value })}
          />
          <Select
            label="Time Horizon"
            options={TIME_HORIZONS}
            value={config.timeHorizon}
            onChange={(e) => onChange({ ...config, timeHorizon: e.target.value })}
          />
          <Select
            label="Report Depth"
            options={REPORT_DEPTHS}
            value={config.reportDepth}
            onChange={(e) => onChange({ ...config, reportDepth: e.target.value })}
          />
          <Select
            label="Language"
            options={['English', 'Chinese']}
            value={config.outputLanguage}
            onChange={(e) => onChange({ ...config, outputLanguage: e.target.value as any })}
          />
          <Select
            label="Format"
            options={['Markdown', 'Word', 'PPT']}
            value={config.outputFormat}
            onChange={(e) => onChange({ ...config, outputFormat: e.target.value as any })}
          />
        </div>
        <div className="mt-4">
           <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Additional Notes / Instructions</label>
           <textarea
             className="w-full px-3 py-2 bg-white dark:bg-slate-900 border border-slate-300 dark:border-slate-700 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-slate-900 dark:text-slate-100 text-sm h-24 resize-none"
             placeholder="Any specific companies to mention, or specific data points required..."
             value={config.additionalNotes}
             onChange={(e) => onChange({ ...config, additionalNotes: e.target.value })}
           />
        </div>
      </Card>
    </div>
  );
};

import React, { useState } from 'react';
import { GeneratedReport } from '../types';
import { Card } from './ui/Card';
import { Button } from './ui/Button';
import { FileText, List, BookOpen, Quote, Download, ArrowLeft, Copy, Check } from 'lucide-react';

interface ReportViewProps {
  report: GeneratedReport;
  onBack: () => void;
}

export const ReportView: React.FC<ReportViewProps> = ({ report, onBack }) => {
  const [activeTab, setActiveTab] = useState<'summary' | 'full' | 'takeaways' | 'citations'>('summary');
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(report.fullReport);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Button variant="ghost" size="sm" onClick={onBack}>
            <ArrowLeft className="w-4 h-4 mr-1" /> Back
          </Button>
          <h2 className="text-2xl font-bold text-slate-900 dark:text-white">Research Report Results</h2>
        </div>
        <div className="flex space-x-2">
           <Button variant="outline" size="sm" onClick={handleCopy}>
              {copied ? <Check className="w-4 h-4 mr-1" /> : <Copy className="w-4 h-4 mr-1" />}
              {copied ? 'Copied' : 'Copy Text'}
           </Button>
           <Button variant="primary" size="sm">
              <Download className="w-4 h-4 mr-1" /> Export PDF
           </Button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm overflow-hidden">
        {/* Tabs */}
        <div className="flex border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50">
          {[
            { id: 'summary', label: 'Executive Summary', icon: FileText },
            { id: 'full', label: 'Full Industry Report', icon: BookOpen },
            { id: 'takeaways', label: 'Key Takeaways (PPT)', icon: List },
            { id: 'citations', label: 'Evidence & Citations', icon: Quote },
          ].map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`
                  flex-1 flex items-center justify-center py-4 text-sm font-medium border-b-2 transition-colors
                  ${isActive 
                    ? 'border-indigo-600 text-indigo-600 bg-white dark:bg-slate-900' 
                    : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800'}
                `}
              >
                <Icon className={`w-4 h-4 mr-2 ${isActive ? 'text-indigo-600' : 'text-slate-400'}`} />
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-8 bg-white dark:bg-slate-900">

          {activeTab === 'summary' && (
