import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedReport, ResearchConfig, Source } from "../types";

// In a real app, this would be chunked and retrieved via vector search.
// Here we simulate RAG by passing the source content in the prompt context window.
const constructPrompt = (config: ResearchConfig, sources: Source[]): string => {
  const sourceContext = sources
    .map((s, i) => `[Source ${i + 1}: ${s.name}] type: ${s.type}\nContent snippet: ${s.content.slice(0, 2000)}...`) // Truncate for demo limits
    .join("\n\n");

  return `
You are a senior industry analyst at CrestPoint AI Research, a top-tier strategy consulting firm.
Your task is to generate a professional industry report based strictly on the user's requirements and the provided knowledge base sources.

RESEARCH PARAMETERS:
- Industry/Topic: ${config.industry}
- Focus Areas: ${config.focusAreas.join(", ")}
- Target Audience: ${config.targetAudience}
- Geography: ${config.geography}
- Time Horizon: ${config.timeHorizon}
- Depth: ${config.reportDepth}
- Language: ${config.outputLanguage}

KNOWLEDGE BASE (CONTEXT):
${sourceContext || "No specific documents provided. Rely on general professional knowledge."}

INSTRUCTIONS:
1. Synthesize the provided sources to answer the research parameters.
2. If sources are insufficient, use your internal knowledge but mark assumptions clearly.
3. Structure the output into 4 distinct parts: Executive Summary, Full Report (Markdown), Key Takeaways (list), and Citations.
4. The Full Report MUST cover: Industry Definition, Market Overview, Key Trends, Competitive Landscape, Policy, Opportunities/Risks, Future Outlook, Recommendations.
5. Be professional, neutral, and data-driven.

Output JSON strictly adhering to the schema.
`;
};

export const generateIndustryReport = async (
  config: ResearchConfig,
  sources: Source[]
): Promise<GeneratedReport> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("API Key not found");

    const ai = new GoogleGenAI({ apiKey });
    const prompt = constructPrompt(config, sources);

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // Use a fast, high-quality model
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            executiveSummary: { type: Type.STRING },
            fullReport: { type: Type.STRING, description: "The detailed report in Markdown format" },
            keyTakeaways: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            citations: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  sourceName: { type: Type.STRING },
                  quote: { type: Type.STRING },
                  pageOrSection: { type: Type.STRING }
                }
              }
            }
          },
          required: ["executiveSummary", "fullReport", "keyTakeaways", "citations"]
        }
      }
    });

    if (!response.text) {
      throw new Error("No response generated");
    }

    const data = JSON.parse(response.text);

    return {
      ...data,
      generationTime: new Date().toISOString(),
      model: "gemini-3-flash-preview"
    };

  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

