import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { ResearchForm } from './components/ResearchForm';
import { SourceManager } from './components/SourceManager';
import { ReportView } from './components/ReportView';
import { Button } from './components/ui/Button';
import { INITIAL_RESEARCH_CONFIG } from './constants';
import { GeneratedReport, ResearchConfig, Source, ViewState } from './types';
import { generateIndustryReport } from './services/geminiService';
import { Sparkles, AlertCircle, Database, Globe } from 'lucide-react';

export default function App() {
  const [viewState, setViewState] = useState<ViewState>('input');
  const [config, setConfig] = useState<ResearchConfig>(INITIAL_RESEARCH_CONFIG);
  const [sources, setSources] = useState<Source[]>([]);
  const [report, setReport] = useState<GeneratedReport | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleAddSource = (source: Source) => {
    setSources(prev => [...prev, source]);
  };

  const handleRemoveSource = (id: string) => {
    setSources(prev => prev.filter(s => s.id !== id));
  };

  const handleGenerate = async () => {
    if (!config.industry) {
      setError("Please enter an Industry or Research Topic.");
      return;
    }
    setError(null);
    setIsGenerating(true);
    setViewState('generating');

    try {
      const result = await generateIndustryReport(config, sources);
      setReport(result);
      setViewState('report');
    } catch (err) {
      console.error(err);
      setError("Failed to generate report. Please check your API key and try again.");
      setViewState('input');
    } finally {
      setIsGenerating(false);
    }
  };

  const renderContent = () => {
    switch (viewState) {
      case 'input':
        return (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <div>
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white">New Research Project</h1>
                <p className="text-slate-500 dark:text-slate-400 mt-1">Configure your AI analyst parameters below.</p>
              </div>

              <ResearchForm config={config} onChange={setConfig} />

              <div className="flex justify-end pt-4">
                <Button 
                  size="lg" 
                  onClick={handleGenerate} 
                  disabled={isGenerating || !config.industry}
                  className="shadow-lg shadow-indigo-500/30"
                >
                  <Sparkles className="w-5 h-5 mr-2" />
                  Generate Industry Report
                </Button>
              </div>
              {error && (
                <div className="bg-red-50 text-red-600 p-4 rounded-lg flex items-center">
                  <AlertCircle className="w-5 h-5 mr-2" />
                  {error}
                </div>
              )}
            </div>

            <div className="lg:col-span-1">
               <div className="sticky top-8">
                  <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Project Sources</h3>
                  <SourceManager 
                    sources={sources} 
                    onAddSource={handleAddSource} 
                    onRemoveSource={handleRemoveSource} 
                  />
               </div>
            </div>
          </div>
        );

      case 'generating':
        return (
          <div className="flex flex-col items-center justify-center h-[60vh] text-center space-y-6">
             <div className="relative w-24 h-24">
                <div className="absolute inset-0 border-4 border-indigo-100 rounded-full animate-pulse"></div>
                <div className="absolute inset-0 border-4 border-t-indigo-600 border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
                <Sparkles className="absolute inset-0 m-auto text-indigo-600 w-8 h-8 animate-pulse" />
             </div>
             <div>
               <h2 className="text-xl font-semibold text-slate-900 dark:text-white">Analyzing Sources & Generating Report</h2>
               <p className="text-slate-500 mt-2 max-w-md mx-auto">
                 Synthesizing trends for {config.industry} based on {sources.length} sources...
               </p>
             </div>
          </div>
        );

      case 'report':
        return report ? <ReportView report={report} onBack={() => setViewState('input')} /> : null;

      case 'knowledge':
        return (
          <div className="space-y-6">
            <h1 className="text-2xl font-bold">Knowledge Base</h1>
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-12 text-center">
              <Database className="w-12 h-12 text-slate-300 mx-auto mb-4" />
              <p className="text-slate-500 italic">Central repository for all uploaded workspace documents (Coming Soon).</p>
            </div>
          </div>
        );

      case 'sources':
        return (
          <div className="space-y-6">
            <h1 className="text-2xl font-bold">Global Sources</h1>
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-12 text-center">
              <Globe className="w-12 h-12 text-slate-300 mx-auto mb-4" />
              <p className="text-slate-500 italic">Real-time external news and API integrations (Coming Soon).</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <Layout activeView={viewState} onChangeView={(v) => setViewState(v)}>
      {renderContent()}
    </Layout>
  );
}

import React, { useState, useRef } from 'react';
import { Upload, Link as LinkIcon, FileText, Trash2, Globe, CheckCircle, Loader2 } from 'lucide-react';
import { Source } from '../types';
import { Button } from './ui/Button';
import { Input } from './ui/Input';

// Define PDF.js types since we load it from CDN
declare const pdfjsLib: any;

interface SourceManagerProps {
  sources: Source[];
  onAddSource: (source: Source) => void;
  onRemoveSource: (id: string) => void;
  compact?: boolean;
}

export const SourceManager: React.FC<SourceManagerProps> = ({ 
  sources, 
  onAddSource, 
  onRemoveSource,
  compact = true 
}) => {
  const [activeTab, setActiveTab] = useState<'docs' | 'urls'>('docs');
  const [urlInput, setUrlInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const extractTextFromPdf = async (file: File): Promise<string> => {
    try {
      const arrayBuffer = await file.arrayBuffer();
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
      const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      let fullText = '';

      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const textContent = await page.getTextContent();
        const pageText = textContent.items.map((item: any) => item.str).join(' ');
        fullText += pageText + '\n\n';
      }
      return fullText;
    } catch (error) {
      console.error('PDF parsing error:', error);
      return `[Error parsing PDF: ${file.name}. Falling back to metadata only.]`;
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setIsProcessing(true);

    // Explicitly cast FileList to File array to resolve 'unknown' type errors for file properties
    const fileArray = Array.from(files) as File[];
    for (const file of fileArray) {
      let content = '';
      if (file.type === 'application/pdf') {
        content = await extractTextFromPdf(file);
      } else {
        content = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onload = (event) => resolve(event.target?.result as string || '');
          reader.readAsText(file);
        });
      }

      const newSource: Source = {
        id: Math.random().toString(36).substr(2, 9),
        type: 'document',
        name: file.name,
        content: content || `[Empty content from ${file.name}]`,
        metadata: {
          size: (file.size / 1024).toFixed(1) + ' KB',
          uploadTime: new Date().toLocaleTimeString(),
          status: 'indexed'
        }
      };
      onAddSource(newSource);
    }

    setIsProcessing(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleUrlAdd = () => {
    if (!urlInput.trim()) return;

    const newSource: Source = {
      id: Math.random().toString(36).substr(2, 9),
      type: 'url',
      name: urlInput.replace(/^https?:\/\//, '').split('/')[0] + ' (Web Page)',
      content: `[Simulated crawled content from ${urlInput}]`,
      metadata: {
        url: urlInput,
        uploadTime: new Date().toLocaleTimeString(),
        status: 'indexed'
      }
    };
    onAddSource(newSource);
    setUrlInput('');
  };

  return (
    <div className="space-y-6">
      <div className="flex space-x-4 border-b border-slate-200 dark:border-slate-800 pb-2">
        <button
          className={`pb-2 text-sm font-medium ${activeTab === 'docs' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
          onClick={() => setActiveTab('docs')}
        >
          <div className="flex items-center"><FileText className="w-4 h-4 mr-2" />Documents</div>
        </button>
        <button
          className={`pb-2 text-sm font-medium ${activeTab === 'urls' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
          onClick={() => setActiveTab('urls')}
        >
          <div className="flex items-center"><LinkIcon className="w-4 h-4 mr-2" />Web Sources</div>
        </button>
      </div>

      {activeTab === 'docs' && (
        <div className="space-y-4">
           <div 
             className={`border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-lg p-8 text-center transition-colors cursor-pointer ${isProcessing ? 'bg-slate-100 cursor-wait' : 'hover:bg-slate-50 dark:hover:bg-slate-900/50'}`} 
             onClick={() => !isProcessing && fileInputRef.current?.click()}
           >
              {isProcessing ? (
                <Loader2 className="mx-auto h-12 w-12 text-indigo-600 animate-spin" />
              ) : (
                <Upload className="mx-auto h-12 w-12 text-slate-400" />
              )}
              <div className="mt-4 text-sm text-slate-600 dark:text-slate-400">
                {isProcessing ? (
                  <span className="font-semibold text-indigo-600">Processing Knowledge Base...</span>
                ) : (
                  <>
                    <span className="font-semibold text-indigo-600 hover:text-indigo-500">Click to upload</span> or drag and drop
                  </>
                )}
              </div>
              <p className="text-xs text-slate-500 mt-2">PDF, TXT, MD, CSV supported</p>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                multiple 
                accept=".pdf,.txt,.md,.csv,.json"
                onChange={handleFileUpload}
                disabled={isProcessing}
              />
           </div>
        </div>
      )}

      {activeTab === 'urls' && (
        <div className="flex space-x-2">
          <Input 
            placeholder="https://example.com/market-report" 
            value={urlInput} 
            onChange={(e) => setUrlInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleUrlAdd()}
          />
          <Button onClick={handleUrlAdd} disabled={!urlInput}>Add URL</Button>
        </div>
      )}

      {/* Source List */}
      <div className={`space-y-3 overflow-y-auto ${compact ? 'max-h-96' : ''}`}>
        {sources.length === 0 && !isProcessing && (
          <div className="text-center py-8 text-slate-500 text-sm">No sources added yet. The AI will rely on general knowledge.</div>
        )}
        {sources.map((source) => (
          <div key={source.id} className="flex items-center justify-between p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg shadow-sm">
            <div className="flex items-center space-x-3 overflow-hidden">
              <div className={`p-2 rounded-lg ${source.type === 'document' ? 'bg-blue-50 text-blue-600' : 'bg-purple-50 text-purple-600'}`}>
                {source.type === 'document' ? <FileText size={18} /> : <Globe size={18} />}
              </div>
              <div className="min-w-0">
                <p className="text-sm font-medium text-slate-900 dark:text-slate-100 truncate">{source.name}</p>
                <div className="flex items-center text-xs text-slate-500 space-x-2">
                  <span>{source.metadata?.size || 'Web Source'}</span>
                  <span>•</span>
