const VisualPreview: React.FC<{ asset: VisualAsset, title: string }> = ({ asset }) => {
  const isVertical = asset.platform === 'xiaohongshu';

  const downloadImage = () => {
    const link = document.createElement('a');
    link.href = `data:image/png;base64,${asset.imageBase64}`;
    link.download = `crestpoint_${asset.platform}_${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className={`relative overflow-hidden rounded-lg shadow-sm group w-full ${isVertical ? 'aspect-[3/4]' : 'aspect-video'}`}>
      <img 
        src={`data:image/png;base64,${asset.imageBase64}`} 
        className="w-full h-full object-cover" 
        alt={`Generated asset for ${asset.platform}`}
      />

      {/* Download Button Overlay */}
      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
        <Button 
          variant="secondary" 
          size="sm" 
          className="opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
          onClick={downloadImage}
        >
          <Download className="w-4 h-4 mr-2" />
          Download Image
        </Button>
      </div>

      <div className="absolute bottom-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
         <div className="bg-black/50 text-white text-[10px] px-2 py-1 rounded backdrop-blur-md">
           {asset.platform}
         </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
