// --- VISUAL ASSETS GENERATION ---

// 1. Generate Prompts ONLY (No Overlay Text)
const generateVisualSpecs = async (report: GeneratedReport): Promise<Omit<SocialVisuals, 'linkedin' | 'twitter' | 'facebook' | 'xiaohongshu'> & { [key: string]: Omit<VisualAsset, 'imageBase64'> }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `
You are a Visual Designer for a B2B AI research brand.
Task: Create 4 unique, high-quality image prompts for social media assets based on the report.
Report Summary: ${report.executiveSummary.slice(0, 500)}...
Key Takeaways: ${report.keyTakeaways.slice(0, 3).join('; ')}

Instructions:
- The user wants CLEAN images with NO TEXT.
- The prompts should describe specific, photorealistic or high-end 3D illustrative scenes relevant to the industry.
- Avoid generic "businessmen shaking hands". Focus on abstract concepts, technology visualizations, or industry-specific environments.

Outputs required for:
1) LinkedIn (1200x627): Professional, corporate context.
2) Twitter (1600x900): High impact, minimal, clean.
3) Facebook (1200x630): Engaging, illustrative.
4) Xiaohongshu (1080x1440): Vertical, lifestyle or creative abstraction.
`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          linkedin: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          },
          twitter: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          },
          facebook: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          },
          xiaohongshu: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          }
        },
        required: ["linkedin", "twitter", "facebook", "xiaohongshu"]
      }
    }
  });

  const jsonStr = response.text?.trim();
  if (!jsonStr) throw new Error("No visual specs generated");
  return JSON.parse(jsonStr);
};

// 2. Generate Actual Image
const generateImage = async (prompt: string, aspectRatio: '16:9' | '3:4'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  // Using gemini-2.5-flash-image for generation
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { text: prompt + " High quality, photorealistic or 3D render, relevant to topic, NO TEXT, NO WRITING, NO LETTERS." }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio,
      }
    }
  });

  // Extract base64 image
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return part.inlineData.data;
    }
  }
  throw new Error("No image data returned");
};

export const generateSocialAssets = async (report: GeneratedReport): Promise<SocialVisuals> => {
  try {
    // Step 1: Get Specs
    const specs = await generateVisualSpecs(report);

    // Step 2: Generate Images in Parallel
    const [liImg, twImg, fbImg, xhsImg] = await Promise.all([
      generateImage(specs.linkedin.prompt, '16:9'),
      generateImage(specs.twitter.prompt, '16:9'),
      generateImage(specs.facebook.prompt, '16:9'),
      generateImage(specs.xiaohongshu.prompt, '3:4')
    ]);

    return {
      linkedin: { ...specs.linkedin, platform: 'linkedin', imageBase64: liImg } as VisualAsset,
      twitter: { ...specs.twitter, platform: 'twitter', imageBase64: twImg } as VisualAsset,
      facebook: { ...specs.facebook, platform: 'facebook', imageBase64: fbImg } as VisualAsset,
      xiaohongshu: { ...specs.xiaohongshu, platform: 'xiaohongshu', imageBase64: xhsImg } as VisualAsset,
    };
  } catch (error) {
    console.error("Visual Asset Generation Error:", error);
    throw error;
  }
};

