                      isLoading={isGeneratingVisuals}
                      className={!socialVisuals ? "bg-emerald-600 hover:bg-emerald-700 text-white" : ""}
                    >
                      <ImageIcon className="w-4 h-4 mr-2" />
                      {socialVisuals ? 'Regenerate Images' : 'Generate Images'}
