                      platformKey="linkedin"
                      post={socialPosts?.linkedin}
                      visual={socialVisuals?.linkedin}
                      onCopy={() => socialPosts && handleCopy(socialPosts.linkedin.content, 'linkedin')}
                      isCopied={copyStates['linkedin']}
