                    <UnifiedSocialCard 
                      icon={Twitter} 
                      platformName="X (Twitter Thread)"
                      platformKey="twitter"
                      post={socialPosts?.twitter}
                      visual={socialVisuals?.twitter}
                      onCopy={() => socialPosts && handleCopy(socialPosts.twitter.content, 'twitter')}
                      isCopied={copyStates['twitter']}
                    />
                    <UnifiedSocialCard 
                      icon={Facebook} 
                      platformName="Facebook"
                      platformKey="facebook"
                      post={socialPosts?.facebook}
                      visual={socialVisuals?.facebook}
                      onCopy={() => socialPosts && handleCopy(socialPosts.facebook.content, 'facebook')}
                      isCopied={copyStates['facebook']}
                    />
                    <UnifiedSocialCard 
                      icon={Share2} 
                      platformName="Xiaohongshu"
                      platformKey="xiaohongshu"
                      post={socialPosts?.xiaohongshu}
                      visual={socialVisuals?.xiaohongshu}
                      onCopy={() => socialPosts && handleCopy(socialPosts.xiaohongshu.content, 'xhs')}
                      isCopied={copyStates['xhs']}
                    />
