               ) : (
                 <div className="text-center py-20 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-dashed border-slate-300 dark:border-slate-700">
                    <Share2 className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                    <p className="text-slate-500 font-medium">Ready to amplify your research? <br/>Click "Generate Copy" to start.</p>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

interface UnifiedSocialCardProps {
