  platformName: string;
  platformKey: string;
  post?: SocialPostContent;
  visual?: VisualAsset;
  onCopy: () => void;
  isCopied: boolean;
}

const UnifiedSocialCard: React.FC<UnifiedSocialCardProps> = ({ 
  icon: Icon, 
  platformName, 
  post, 
  visual, 
  onCopy, 
  isCopied 
}) => {
  // Utility to clean text from accidental markdown bolding
  const cleanContent = (text: string) => text.replace(/\*\*/g, '').replace(/__/g, '');

  return (
    <Card className="flex flex-col h-full border-t-4 border-t-indigo-500 shadow-md">
      {/* Header: Platform & Title */}
