// 1. Generate Prompts & Text Specs using Gemini 3 Flash
const generateVisualSpecs = async (report: GeneratedReport): Promise<Omit<SocialVisuals, 'linkedin' | 'twitter' | 'facebook' | 'xiaohongshu'> & { [key: string]: Omit<VisualAsset, 'imageBase64'> }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `
You are a professional visual designer for an enterprise-grade AI research platform.
Your task is to generate a HIGH-QUALITY, TEXT-FREE visual image prompt based solely on an industry research topic.

================================================
INPUT
================================================
- Industry Research Topic: ${report.executiveSummary.split('.')[0]}
- Key Takeaways: ${report.keyTakeaways.slice(0, 2).join('; ')}

================================================
OUTPUT REQUIREMENTS (MANDATORY)
================================================
1) TEXT-FREE IMAGE
- The image must contain NO TEXT
- No titles, no numbers, no words, no symbols, no UI labels
- No watermarks

2) TOPIC-ALIGNED VISUAL CONTENT
- The image must visually represent the research topic conceptually
- Use symbolic or abstract visual metaphors related to the topic
- Avoid generic backgrounds that do not convey meaning

Examples:
- AI Infrastructure → data centers, GPU clusters, network flows, cloud compute
- Enterprise AI → abstract business environments, dashboards, interconnected systems
- Global AI Market → global maps, data flows, digital economies
- Healthcare AI → medical data visualization, AI-assisted diagnostics (no people faces)

3) VISUAL STYLE
- Modern, clean, enterprise-grade
- Professional and credible (not marketing-heavy)
- No cartoon or illustration style
- No stock-photo realism
- No human faces

4) COLOR & AESTHETICS
- Dark or neutral background
- Subtle gradients
- Accent colors allowed (electric blue, neon green, soft cyan)
- Balanced contrast for overlaying future text if needed

5) COMPOSITION
- Clear focal point
- Enough negative space for optional future overlays
- Mobile-friendly readability

================================================
IMPORTANT CONSTRAINTS
================================================
- DO NOT include any text in the image
- DO NOT include charts or readable numbers
- DO NOT include logos unless explicitly provided
- The image must visually communicate the research topic without words

================================================
Output JSON strictly adhering to the schema, returning only the 'prompt' field for each platform.
`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          linkedin: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          },
          twitter: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          },
          facebook: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          },
          xiaohongshu: {
            type: Type.OBJECT,
            properties: { prompt: { type: Type.STRING } }
          }
        },
        required: ["linkedin", "twitter", "facebook", "xiaohongshu"]
      }
    }
  });

  const jsonStr = response.text?.trim();
  if (!jsonStr) throw new Error("No visual specs generated");
  return JSON.parse(jsonStr);
};

// 2. Generate Actual Image using Gemini 2.5 Flash Image
const generateImage = async (prompt: string, aspectRatio: '16:9' | '3:4'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  // Using gemini-2.5-flash-image for generation as per guidelines for general image tasks
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { text: prompt + " --no text --no writing --no symbols --no letters --no numbers. Focus on abstract concepts related to the topic." }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio,
      }
    }
  });

  // Extract base64 image
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return part.inlineData.data;
    }
  }
  throw new Error("No image data returned");
};

export const generateSocialAssets = async (report: GeneratedReport): Promise<SocialVisuals> => {
  try {
    // Step 1: Get Specs (only prompts now)
    const specs = await generateVisualSpecs(report);

    // Step 2: Generate Images in Parallel
    const [liImg, twImg, fbImg, xhsImg] = await Promise.all([
      generateImage(specs.linkedin.prompt, '16:9'),
      generateImage(specs.twitter.prompt, '16:9'),
      generateImage(specs.facebook.prompt, '16:9'),
      generateImage(specs.xiaohongshu.prompt, '3:4')
    ]);

    return {
      linkedin: { platform: 'linkedin', prompt: specs.linkedin.prompt, imageBase64: liImg },
      twitter: { platform: 'twitter', prompt: specs.twitter.prompt, imageBase64: twImg },
      facebook: { platform: 'facebook', prompt: specs.facebook.prompt, imageBase64: fbImg },
      xiaohongshu: { platform: 'xiaohongshu', prompt: specs.xiaohongshu.prompt, imageBase64: xhsImg },
    };
  } catch (error) {
    console.error("Visual Asset Generation Error:", error);
    throw error;
  }
};

