const generateVisualSpecs = async (report: GeneratedReport): Promise<any> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key missing");

  const ai = new GoogleGenAI({ apiKey });
  const prompt = `
You are a professional visual designer. Generate text-free image prompts for an enterprise-grade AI research platform.
Topic: ${report.executiveSummary.split('.')[0]}

Output JSON with a 'prompt' field for: linkedin, twitter, facebook, xiaohongshu.
PROMPTS MUST BE VISUAL ONLY. NO TEXT.
`;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: { parts: [{ text: prompt }] },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          linkedin: { type: Type.OBJECT, properties: { prompt: { type: Type.STRING } }, required: ["prompt"] },
          twitter: { type: Type.OBJECT, properties: { prompt: { type: Type.STRING } }, required: ["prompt"] },
          facebook: { type: Type.OBJECT, properties: { prompt: { type: Type.STRING } }, required: ["prompt"] },
          xiaohongshu: { type: Type.OBJECT, properties: { prompt: { type: Type.STRING } }, required: ["prompt"] }
        },
        required: ["linkedin", "twitter", "facebook", "xiaohongshu"]
      }
    }
  });

  let jsonStr = response.text?.trim() || "";
  if (jsonStr.startsWith("```")) {
    jsonStr = jsonStr.replace(/^```(?:json)?\n?/, "").replace(/\n?```$/, "");
  }
  return JSON.parse(jsonStr);
};

const generateImage = async (prompt: string, aspectRatio: '16:9' | '3:4'): Promise<string> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key missing");

  const ai = new GoogleGenAI({ apiKey });
  const finalPrompt = prompt + " --no text --no writing --no symbols. Enterprise-grade, abstract, clean background.";

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: finalPrompt }] },
    config: {
      imageConfig: { aspectRatio: aspectRatio }
    }
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) return part.inlineData.data;
  }
  throw new Error("No image data returned");
};

export const generateSocialAssets = async (report: GeneratedReport): Promise<SocialVisuals> => {
  try {
    const specs = await generateVisualSpecs(report);

    const [liImg, twImg, fbImg, xhsImg] = await Promise.all([
      generateImage(specs.linkedin.prompt, '16:9'),
      generateImage(specs.twitter.prompt, '16:9'),
      generateImage(specs.facebook.prompt, '16:9'),
      generateImage(specs.xiaohongshu.prompt, '3:4')
    ]);

    return {
      linkedin: { platform: 'linkedin', prompt: specs.linkedin.prompt, imageBase64: liImg },
      twitter: { platform: 'twitter', prompt: specs.twitter.prompt, imageBase64: twImg },
      facebook: { platform: 'facebook', prompt: specs.facebook.prompt, imageBase64: fbImg },
      xiaohongshu: { platform: 'xiaohongshu', prompt: specs.xiaohongshu.prompt, imageBase64: xhsImg },
    };
  } catch (error) {
    console.error("Visual Asset Generation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ResearchForm } from './components/ResearchForm';
import { SourceManager } from './components/SourceManager';
import { ReportView } from './components/ReportView';
import { Button } from './components/ui/Button';
import { INITIAL_RESEARCH_CONFIG, MAX_DOC_SOURCES, MAX_URL_SOURCES } from './constants';
import { GeneratedReport, ResearchConfig, Source, ViewState } from './types';
import { generateIndustryReport } from './services/geminiService';
import { Sparkles, AlertCircle, Database, Globe, Trash2 } from 'lucide-react';

export default function App() {
  const [viewState, setViewState] = useState<ViewState>('input');
  const [config, setConfig] = useState<ResearchConfig>(INITIAL_RESEARCH_CONFIG);
  const [sources, setSources] = useState<Source[]>([]); // Project Sources

  // Persistent States
  const [knowledgeBase, setKnowledgeBase] = useState<Source[]>(() => {
    const saved = localStorage.getItem('crestpoint_kb');
    return saved ? JSON.parse(saved) : [];
  });

  const [globalSources, setGlobalSources] = useState<Source[]>(() => {
    const saved = localStorage.getItem('crestpoint_gs');
    return saved ? JSON.parse(saved) : [];
  });

  const [report, setReport] = useState<GeneratedReport | null>(() => {
    const saved = localStorage.getItem('crestpoint_last_report');
    return saved ? JSON.parse(saved) : null;
  });

  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [warningMessage, setWarningMessage] = useState<string | null>(null);

  // Persistence Effects
  useEffect(() => {
    localStorage.setItem('crestpoint_kb', JSON.stringify(knowledgeBase));
  }, [knowledgeBase]);

  useEffect(() => {
    localStorage.setItem('crestpoint_gs', JSON.stringify(globalSources));
  }, [globalSources]);

  useEffect(() => {
    if (report) {
      localStorage.setItem('crestpoint_last_report', JSON.stringify(report));
    }
  }, [report]);

  const handleSourceManagerWarning = (message: string) => {
    setWarningMessage(message);
    setTimeout(() => setWarningMessage(null), 5000);
  };

  const handleClearAllData = () => {
    if (confirm("Are you sure you want to clear all saved research and sources? This cannot be undone.")) {
      setKnowledgeBase([]);
      setGlobalSources([]);
      setReport(null);
      setSources([]);
      localStorage.clear();
      window.location.reload();
    }
  };

  const handleGenerate = async () => {
    if (!config.industry) {
      setError("Please enter an Industry or Research Topic.");
      return;
    }
    setError(null);
    setWarningMessage(null);
    setIsGenerating(true);
    setViewState('generating');

    try {
      const allSources = [...sources, ...knowledgeBase, ...globalSources];
      const result = await generateIndustryReport(config, allSources);
      setReport(result);
      setViewState('report');
    } catch (err: any) {
      console.error("Research Generation Error:", err);
      // Display the actual error message to help diagnostics
      setError(err.message || "Failed to generate report. Please check your network and try again.");
      setViewState('input');
    } finally {
      setIsGenerating(false);
    }
  };

  const renderContent = () => {
    switch (viewState) {
      case 'input':
        return (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <div className="flex justify-between items-start">
                <div>
                  <h1 className="text-2xl font-bold text-slate-900 dark:text-white">New Research Project</h1>
                  <p className="text-slate-500 dark:text-slate-400 mt-1">Configure your AI analyst parameters below.</p>
                </div>
                {report && (
                  <Button variant="ghost" size="sm" onClick={() => setViewState('report')} className="text-indigo-600">
                    View Last Report
                  </Button>
                )}
              </div>

              <ResearchForm config={config} onChange={setConfig} />

              <div className="flex justify-end pt-4 space-x-4">
                <Button variant="ghost" onClick={handleClearAllData} className="text-slate-400 hover:text-red-500">
                  <Trash2 className="w-4 h-4 mr-2" /> Reset Workspace
                </Button>
                <Button 
                  size="lg" 
                  onClick={handleGenerate} 
                  disabled={isGenerating || !config.industry}
                  className="shadow-lg shadow-indigo-500/30"
                >
                  <Sparkles className="w-5 h-5 mr-2" />
                  Generate Industry Report
                </Button>
              </div>
              {error && (
                <div role="alert" className="bg-red-50 text-red-600 p-4 rounded-lg flex items-start">
                  <AlertCircle className="w-5 h-5 mr-2 mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="font-bold">Error encountered:</p>
                    <p className="text-sm">{error}</p>
                    <p className="mt-2 text-xs opacity-75">Tip: If you just added your API key, you must Redeploy on Vercel for changes to take effect.</p>
                  </div>
                </div>
              )}
              {warningMessage && ( 
                <div role="alert" className="bg-amber-50 text-amber-700 p-4 rounded-lg flex items-center">
                  <AlertCircle className="w-5 h-5 mr-2" />
                  {warningMessage}
                </div>
              )}
            </div>

            <div className="lg:col-span-1">
               <div className="sticky top-8 space-y-6">
                  <div>
                    <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Project Sources ({sources.length} / {MAX_DOC_SOURCES})</h3>
                    <SourceManager 
                      sources={sources} 
                      onAddSource={(s) => setSources(prev => [...prev, s])} 
                      onRemoveSource={(id) => setSources(prev => prev.filter(s => s.id !== id))}
                      compact={true}
                      maxSources={MAX_DOC_SOURCES}
                      sourceType="document"
                      onShowWarning={handleSourceManagerWarning}
                    />
                  </div>

                  {globalSources.length > 0 && (
                     <div className="p-4 bg-purple-50 dark:bg-purple-900/20 rounded-lg border border-purple-100 dark:border-purple-800">
                        <div className="flex items-center text-purple-700 dark:text-purple-300 mb-2">
                           <Globe className="w-4 h-4 mr-2" />
                           <span className="font-semibold text-sm">Global Sources Syncing</span>
                        </div>
                        <p className="text-xs text-slate-600 dark:text-slate-400">
                           AI will reference <strong>{globalSources.length}</strong> persistent web sources.
                        </p>
                     </div>
                  )}

                  {knowledgeBase.length > 0 && (
                    <div className="p-4 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg border border-indigo-100 dark:border-indigo-800">
                      <div className="flex items-center text-indigo-700 dark:text-indigo-300 mb-2">
                        <Database className="w-4 h-4 mr-2" />
                        <span className="font-semibold text-sm">Knowledge Base Syncing</span>
                      </div>
                      <p className="text-xs text-slate-600 dark:text-slate-400">
                        AI will reference <strong>{knowledgeBase.length}</strong> persistent private documents.
                      </p>
                    </div>
                  )}
               </div>
            </div>
          </div>
        );

      case 'generating':
        return (
          <div className="flex flex-col items-center justify-center h-[60vh] text-center space-y-6">
             <div className="relative w-24 h-24">
                <div className="absolute inset-0 border-4 border-indigo-100 rounded-full animate-pulse"></div>
                <div className="absolute inset-0 border-4 border-t-indigo-600 border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin"></div>
                <Sparkles className="absolute inset-0 m-auto text-indigo-600 w-8 h-8 animate-pulse" />
             </div>
             <div>
               <h2 className="text-xl font-semibold text-slate-900 dark:text-white">Synthesizing Professional Insights</h2>
               <p className="text-slate-500 mt-2 max-w-md mx-auto">
                 Analyzing {sources.length + knowledgeBase.length + globalSources.length} sources...
               </p>
             </div>
          </div>
        );

      case 'report':
        return report ? <ReportView report={report} onBack={() => setViewState('input')} /> : null;

      case 'knowledge':
        return (
          <div className="space-y-6">
             <div className="flex items-center justify-between">
                <div>
                   <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Persistent Knowledge Base</h1>
                   <p className="text-slate-500 dark:text-slate-400 mt-1">These documents are saved locally and used for all future reports.</p>
                </div>
                <div className="bg-indigo-100 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300 px-3 py-1 rounded-full text-sm font-medium">
                  {knowledgeBase.length} / {MAX_DOC_SOURCES} Documents
                </div>
             </div>
             {warningMessage && ( 
                <div className="bg-amber-50 text-amber-700 p-4 rounded-lg flex items-center">
                  <AlertCircle className="w-5 h-5 mr-2" />
                  {warningMessage}
                </div>
              )}
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-6 shadow-sm">
                <SourceManager 
                  sources={knowledgeBase} 
                  onAddSource={(s) => setKnowledgeBase(prev => [...prev, s])} 
                  onRemoveSource={(id) => setKnowledgeBase(prev => prev.filter(s => s.id !== id))} 
                  compact={false}
                  maxSources={MAX_DOC_SOURCES}
                  sourceType="document"
                  onShowWarning={handleSourceManagerWarning}
                />
            </div>
          </div>
        );

      case 'sources': 
        return (
          <div className="space-y-6">
             <div className="flex items-center justify-between">
                <div>
                   <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Global Web Sources</h1>
                   <p className="text-slate-500 dark:text-slate-400 mt-1">URLs stored here provide persistent industry context for your analyst.</p>
                </div>
                <div className="bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300 px-3 py-1 rounded-full text-sm font-medium">
                  {globalSources.length} / {MAX_URL_SOURCES} URLs
                </div>
             </div>
             {warningMessage && ( 
                <div className="bg-amber-50 text-amber-700 p-4 rounded-lg flex items-center">
                  <AlertCircle className="w-5 h-5 mr-2" />
                  {warningMessage}
                </div>
              )}
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-6 shadow-sm">
                <SourceManager 
                  sources={globalSources} 
                  onAddSource={(s) => setGlobalSources(prev => [...prev, s])} 
                  onRemoveSource={(id) => setGlobalSources(prev => prev.filter(s => s.id !== id))} 
                  compact={false}
                  maxSources={MAX_URL_SOURCES}
                  sourceType="url"
                  onShowWarning={handleSourceManagerWarning}
                />
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <Layout activeView={viewState} onChangeView={(v) => {
      setViewState(v);
      setWarningMessage(null); 
      setError(null); 
    }}>
      {renderContent()}
    </Layout>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { GeneratedReport, ResearchConfig, Source, SocialPosts, SocialVisuals, VisualAsset } from "../types";

const getApiKey = () => {
  const key = process.env.API_KEY;
  // In Vite builds, if the env var is missing, it might be baked as the literal string "undefined"
  if (!key || key === 'undefined' || key.length < 5) {
    throw new Error("Gemini API Key is missing or invalid. Please ensure API_KEY is set in Vercel and you have TRIGGERED A REDEPLOY.");
  }
  return key;
};

const constructPrompt = (config: ResearchConfig, sources: Source[]): string => {
  const sourceContext = sources
    .map((s, i) => `[Source ${i + 1}: ${s.name}] type: ${s.type}\nContent snippet: ${s.content.slice(0, 2000)}...`) 
    .join("\n\n");

  return `
You are a senior industry analyst at CrestPoint AI Brain, a top-tier strategy consulting firm.
Your task is to generate a professional industry report based strictly on the user's requirements and the provided knowledge base.

RESEARCH PARAMETERS:
- Industry/Topic: ${config.industry}
- Focus Areas: ${config.focusAreas.join(", ")}
- Target Audience: ${config.targetAudience}
- Geography: ${config.geography}
- Time Horizon: ${config.timeHorizon}
- Depth: ${config.reportDepth}
- Language: ${config.outputLanguage}

KNOWLEDGE BASE (CONTEXT):
${sourceContext || "No specific documents provided. Rely on general professional knowledge."}

STRICT INSTRUCTIONS FOR THE "fullReport" SECTION:
1. Remove all AI-style formatting symbols, including but not limited to Markdown headings (##, ###) and bold markers (**).
2. Convert the entire content into natural paragraphs with clear logical flow.
3. Keep all original facts and data points.
4. Use formal, neutral, and analytical language.
5. Ensure the final output looks like it was written by a human analyst.
6. OUTPUT FORMAT for "fullReport": Plain text only, double newlines between paragraphs.

Output JSON strictly adhering to the schema.
`;
};

export const generateIndustryReport = async (
  config: ResearchConfig,
  sources: Source[]
): Promise<GeneratedReport> => {
  const apiKey = getApiKey();

  try {
    const ai = new GoogleGenAI({ apiKey });
    const prompt = constructPrompt(config, sources);

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: { parts: [{ text: prompt }] },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            executiveSummary: { type: Type.STRING },
            fullReport: { type: Type.STRING },
            keyTakeaways: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            citations: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  sourceName: { type: Type.STRING },
                  quote: { type: Type.STRING },
                  pageOrSection: { type: Type.STRING }
                }
              }
            }
          },
          required: ["executiveSummary", "fullReport", "keyTakeaways", "citations"]
        }
      }
    });

    let jsonStr = response.text?.trim() || "";
    if (jsonStr.startsWith("```")) {
      jsonStr = jsonStr.replace(/^```(?:json)?\n?/, "").replace(/\n?```$/, "");
    }

    if (!jsonStr) throw new Error("No response generated");

    const data = JSON.parse(jsonStr);
    return {
      ...data,
      generationTime: new Date().toISOString(),
      model: "gemini-3-flash-preview"
    };
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

