import { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel } from "docx";
import pptxgen from "pptxgenjs";
import { generateSocialMediaContent, generateSocialAssets } from '../services/geminiService';

interface ReportViewProps {
  report: GeneratedReport;
  onBack: () => void;
}

export const ReportView: React.FC<ReportViewProps> = ({ report, onBack }) => {
  const [activeTab, setActiveTab] = useState<'summary' | 'full' | 'takeaways' | 'citations' | 'social'>('summary');
  const [copied, setCopied] = useState(false);
  const [isExportingWord, setIsExportingWord] = useState(false);
  const [isExportingPDF, setIsExportingPDF] = useState(false);
  const [isExportingPPT, setIsExportingPPT] = useState(false);

  const [socialPosts, setSocialPosts] = useState<SocialPosts | null>(null);
  const [socialVisuals, setSocialVisuals] = useState<SocialVisuals | null>(null);
  const [isGeneratingSocial, setIsGeneratingSocial] = useState(false);
  const [isGeneratingVisuals, setIsGeneratingVisuals] = useState(false);
  const [copyStates, setCopyStates] = useState<Record<string, boolean>>({});

  const handleCopy = (text: string, key: string = 'general') => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    if (key === 'general') {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    } else {
        setCopyStates(prev => ({ ...prev, [key]: true }));
        setTimeout(() => setCopyStates(prev => ({ ...prev, [key]: false })), 2000);
    }
  };

  const handleGenerateSocial = async () => {
    setIsGeneratingSocial(true);
    try {
      const posts = await generateSocialMediaContent(report);
      setSocialPosts(posts);
    } catch (err) {
      console.error("Social generation failed:", err);
      alert("Failed to generate social media content. Please try again.");
    } finally {
      setIsGeneratingSocial(false);
    }
  };

  const handleGenerateVisuals = async () => {
    setIsGeneratingVisuals(true);
    try {
      const visuals = await generateSocialAssets(report);
      setSocialVisuals(visuals);
    } catch (err) {
      console.error("Visual generation failed:", err);
      alert("Failed to generate visual assets. Please try again.");
    } finally {
      setIsGeneratingVisuals(false);
    }
  };

  const handleExportMarkdown = () => {
    const date = new Date(report.generationTime).toLocaleDateString();
    // Reconstruct the exact template the user requested
    const markdownContent = `# Industry Report
**Prepared by:** CrestPoint AI Brain
**Date:** ${date}
**Version:** v1.0

---

## Executive Summary
${report.executiveSummary}

### Key Takeaways
${report.keyTakeaways.map(t => `- ${t}`).join('\n')}

---

${report.fullReport}

---

## Methodology & Sources
### Research Methodology
- AI-driven synthesis of provided documents and global web sources.
- Pattern matching across market data, competitive intelligence, and strategic frameworks.

### Key Sources
${report.citations.map(c => `- **${c.sourceName}**: "${c.quote}"`).join('\n')}

---

## Disclaimer
This report is for informational purposes only and does not constitute investment advice.
`;

    const blob = new Blob([markdownContent], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `CrestPoint_Report_${Date.now()}.md`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleExportPDF = () => {
    setIsExportingPDF(true);
    setTimeout(() => {
      window.focus();
      window.print();
      setIsExportingPDF(false);
    }, 250);
  };

  const handleExportPPT = async () => {
    setIsExportingPPT(true);
    try {
      const pres = new pptxgen();

      // Title Slide
      let titleSlide = pres.addSlide();
      titleSlide.background = { color: "F1F5F9" };
      titleSlide.addText("CrestPoint AI Brain", {
        x: 0, y: "35%", w: "100%", align: "center", fontSize: 44, bold: true, color: "4F46E5"
      });
      titleSlide.addText("Strategic Industry Research Analysis", {
        x: 0, y: "50%", w: "100%", align: "center", fontSize: 24, color: "64748B"
      });
      titleSlide.addText(`Generated on: ${new Date(report.generationTime).toLocaleDateString()}`, {
